function M.setup_ui_close(on_close)
  if close_autocmd_id then nvim_del_autocmd(close_autocmd_id) end

  close_autocmd_id = nvim_create_autocmd("QuitPre", {
    callback = function()
      local win = nvim_get_current_win()
      local buf = nvim_win_get_buf(win)
      local buf_name = nvim_buf_get_name(buf)
      if buf_name:find("^reposcope://") then on_close() end
    end,
  })
end

function M.list_active_prompt_keymaps()
  local configured = cfg_get_option("prompt_keymaps") or {}
  local rows = {}

  for _, action in ipairs(ACTION_ORDER) do
    local handler = prompt_keymap_actions[action]
    local lhs_cfg = configured[action]
    if handler and lhs_cfg and lhs_cfg ~= "" then
      local keys = type(lhs_cfg) == "table" and lhs_cfg or { lhs_cfg }
      rows[#rows + 1] = { action = action, lhs = keys, desc = handler.desc }
    end
  end

  return rows
end

local function build_routes()
  local routes = {}
  for name, entry in pairs(subcommands) do
    local args
    if entry.complete then
      local type_name = "REPOSCOPE_" .. name:upper():gsub("%-", "_")
      composer.register_type(type_name, {
        validate = function(raw) return true, raw, nil end,
        complete = function(arg_lead)
          local ok, list = pcall(entry.complete, arg_lead)
          return (ok and list) or {}
        end,
      })
      args = { { name = "a1", type = type_name, optional = true } }
    end
    routes[#routes + 1] = {
      path = { name },
      args = args,
      desc = entry.desc,
      run = function(ctx)
        local fargs = {}
        if args and ctx.args.a1 ~= nil then fargs[1] = ctx.args.a1 end
        for _, t in ipairs(ctx.rest) do
          fargs[#fargs + 1] = t
        end
        entry.run(fargs)
      end,
    }
  end
  return routes
end

function M.get(owner, repo_name)
  local ok, source = M.has(owner, repo_name)
  if not ok then return nil end

  if source == "ram" then
    return M.get_ram(owner, repo_name)
  elseif source == "file" then
    return M.get_file(owner, repo_name)
  end
end

function M.build_query(input)
  local provider = _resolve_provider()
  if not provider then return "" end
  return provider.query_builder.build(input)
end

function M.build_command(clone_type, repo_url, output_dir)
  local branch = "main"

  if clone_type == "curl" or clone_type == "wget" then
    local base = repo_url:gsub("%.git$", "")
    local zip_url = base .. "/archive/" .. branch .. ".zip"

    if clone_type == "curl" then
      return { "curl", "-L", "-o", output_dir .. ".zip", zip_url }
    else
      return { "wget", "-O", output_dir .. ".zip", zip_url }
    end
  end

  return { "git", "clone", repo_url, output_dir }
end

function M.build_url(query)
  local encoded_query = urlencode(query or "")
