function M.register_request(uuid)
  if uuid and type(uuid) == "string" and uuid ~= "" then M.requests[uuid] = false end
end

function M.start_request(uuid)
  if M.requests[uuid] == false then M.requests[uuid] = true end
end

function M.prompt_filter()
  kit.input({
    title = " Filter Repositories ",
    width = 40,
    on_submit = function(input)
      if not input or input == "" then return end
      apply_filter(input)
    end,
  })
end

local function _is_html_content(content)
  return content:match("<html>") or content:match("<head>") or content:match("<body>") or content:match("<div>")
end

function M.prompt_sort()
  vim.ui.select({ "name", "owner", "stars", "relevance" }, {
    prompt = "Sort repositories by:",
  }, function(choice)
    if not choice then return end
    M.apply_sort(choice)
  end)
end

function M.dedupe_list(list)
  if type(list) ~= "table" then return {} end
  return require("lib.lua.tables").dedup_list(list)
end

function M.urlencode(str)
  -- Replace newline characters with CRLF for URL encoding
  local crlf_encoded = str:gsub("\n", "\r\n")
  return require("lib.lua.strings.encoding").url_encode(crlf_encoded)
end

function M.safe_call(fn, ...)
  local args = { ... }
  local ok, result = pcall(function() return fn(unpack(args)) end)

  if not ok then return {
    ok = false,
    result = nil,
    err = result,
  } end

  return {
    ok = true,
    result = result,
    err = nil,
  }
end

function M.new_error(type, message, details)
  return {
    type = type,
    message = message,
    details = details,
  }
end

function M.get_session_requests()
  return {
    successful = M.req_count.successful,
    failed = M.req_count.failed,
    cache_hitted = M.req_count.cache_hitted,
    fcache_hitted = M.req_count.fcache_hitted,
  }
end

function M.is_git_repo(path)
  local stat = uv.fs_stat(path .. "/.git")
  return stat ~= nil and (stat.type == "directory" or stat.type == "file")
end

function M.resolve_base_dir(override)
  local dir = override

  if not dir or dir == "" then dir = config.options.clone and config.options.clone.std_dir or nil end

  if not dir or dir == "" then return nil end

  return fnamemodify(expand(dir), ":p"):gsub("[\\/]+$", "")
end
